// EXP-1430: node --test .github/actions/bump-versions/
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, appendFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, dirname } from 'node:path'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { bump, bumpCargoLock, nextVersion, parseArgs, BumpError } from './bump.mjs'

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), `bump.mjs`)

const CARGO_TOML = `[workspace]\nmembers = ["crates/*"]\n\n[workspace.package]\nedition = "2021"\nversion = "0.14.83"\nlicense = "Apache-2.0"\n\n[workspace.dependencies]\nserde = { version = "1.0.0" }\n`

const CARGO_LOCK = `# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "anyhow"
version = "0.14.83"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "api"
version = "0.14.83"
dependencies = [
 "anyhow",
]

[[package]]
name = "vendored"
version = "0.1.0"

[[package]]
name = "voice"
version = "0.14.83"
`

const GRADLE = `android {\n    defaultConfig {\n        versionCode = 157\n        versionName = "0.14.74"\n    }\n    productFlavors {\n        create("staging") {\n            versionNameSuffix = "-staging"\n        }\n    }\n}\n`
const SWIFT = `let appMarketingVersion = "0.14.72"\nlet appBuildVersion = "220"\nlet stagingBuildVersion = String(Int(appBuildVersion)! + 1)\n`
const EXCLUDED = `[\n  {\n    "package": "api@0.14.83",\n    "reason": "workspace member — ours"\n  },\n  {\n    "package": "anyhow@0.14.83",\n    "reason": "dev-dependency only"\n  },\n  {\n    "package": "voice@0.14.83",\n    "reason": "workspace member — ours"\n  }\n]\n`

const CONFIG = {
  products: {
    desktop: {
      tags: [`desktop-v{version}`, `cli-v{version}`],
      fields: [
        { file: `Cargo.toml`, pattern: `^\\[workspace\\.package\\]\\n(?:(?!\\[)[^\\n]*\\n)*?version = "(?<value>[^"]+)"$` },
        { file: `excluded.json`, pattern: `"package": "[^"@]+@(?<value>{current})",\\n\\s*"reason": "workspace member`, all: true },
      ],
      cargoLock: `Cargo.lock`,
    },
    android: {
      tags: [`android-v{version}`],
      fields: [
        { file: `app/build.gradle.kts`, pattern: `^\\s*versionName = "(?<value>[^"]+)"$` },
        { file: `app/build.gradle.kts`, pattern: `^\\s*versionCode = (?<value>\\d+)$`, kind: `build`, name: `versionCode` },
      ],
    },
    ios: {
      tags: [`ios-v{version}`],
      fields: [
        { file: `Project.swift`, pattern: `^let appMarketingVersion = "(?<value>[^"]+)"$` },
        { file: `Project.swift`, pattern: `^let appBuildVersion = "(?<value>\\d+)"$`, kind: `build`, name: `appBuildVersion`, step: 2 },
      ],
    },
    web: { tags: [`v{version}`], versionFromTags: `v` },
  },
}

const fixture = () => {
  const root = mkdtempSync(join(tmpdir(), `bump-versions-`))
  mkdirSync(join(root, `app`))
  writeFileSync(join(root, `Cargo.toml`), CARGO_TOML)
  writeFileSync(join(root, `Cargo.lock`), CARGO_LOCK)
  writeFileSync(join(root, `excluded.json`), EXCLUDED)
  writeFileSync(join(root, `app/build.gradle.kts`), GRADLE)
  writeFileSync(join(root, `Project.swift`), SWIFT)
  writeFileSync(join(root, `release-versions.json`), JSON.stringify(CONFIG))
  return root
}
const read = (root, f) => readFileSync(join(root, f), `utf8`)

test(`nextVersion: patch, minor, major, explicit`, () => {
  assert.equal(nextVersion(`0.14.83`, `patch`), `0.14.84`)
  assert.equal(nextVersion(`0.14.83`, `minor`), `0.15.0`)
  assert.equal(nextVersion(`0.14.83`, `major`), `1.0.0`)
  assert.equal(nextVersion(`0.14.83`, `0.14.90`), `0.14.90`)
  assert.throws(() => nextVersion(`0.14.83`, `0.14.83`), /not above/)
  assert.throws(() => nextVersion(`0.14.83`, `0.14.9`), /not above/)
  assert.throws(() => nextVersion(`0.14.83`, `latest`), /not a x\.y\.z/)
})

test(`parseArgs skips none/empty and rejects duplicates`, () => {
  const o = parseArgs([`--config`, `c.json`, `--dry-run`, `desktop=patch`, `ios=none`, `web=`, `android=0.14.75`])
  assert.deepEqual(o.requests, { desktop: `patch`, android: `0.14.75` })
  assert.equal(o.dryRun, true)
  assert.throws(() => parseArgs([`--config`, `c`, `a=patch`, `a=minor`]), /twice/)
  assert.throws(() => parseArgs([`desktop=patch`]), /--config/)
})

test(`desktop: Cargo.toml, every workspace lock entry, the all-matches inventory`, () => {
  const root = fixture()
  const { results } = bump({ config: CONFIG, requests: { desktop: `patch` }, root })
  assert.deepEqual(results[0].tags, [`desktop-v0.14.84`, `cli-v0.14.84`])
  assert.match(read(root, `Cargo.toml`), /\[workspace\.package\]\nedition = "2021"\nversion = "0\.14\.84"/)
  assert.match(read(root, `Cargo.toml`), /serde = \{ version = "1\.0\.0" \}/)
  const lock = read(root, `Cargo.lock`)
  assert.match(lock, /name = "api"\nversion = "0\.14\.84"/)
  assert.match(lock, /name = "voice"\nversion = "0\.14\.84"/)
  // a registry crate on the same version and a workspace crate on its own version stay
  assert.match(lock, /name = "anyhow"\nversion = "0\.14\.83"\nsource/)
  assert.match(lock, /name = "vendored"\nversion = "0\.1\.0"/)
  assert.match(lock, /^version = 4$/m)
  const ex = read(root, `excluded.json`)
  assert.match(ex, /"api@0\.14\.84"/)
  assert.match(ex, /"voice@0\.14\.84"/)
  assert.match(ex, /"anyhow@0\.14\.83"/)
})

test(`bumpCargoLock fails when no workspace package is on the old version`, () => {
  assert.throws(() => bumpCargoLock(CARGO_LOCK, `9.9.9`, `9.9.10`), /no workspace package/)
  const { changed } = bumpCargoLock(CARGO_LOCK, `0.14.83`, `0.15.0`)
  assert.deepEqual(changed, [`api`, `voice`])
})

test(`build numbers: android +1, ios +2 (staging takes the one in between)`, () => {
  const root = fixture()
  const { results } = bump({ config: CONFIG, requests: { android: `0.14.75`, ios: `minor` }, root })
  assert.deepEqual(results.map((r) => r.builds), [{ versionCode: `158` }, { appBuildVersion: `222` }])
  assert.match(read(root, `app/build.gradle.kts`), /versionCode = 158\n        versionName = "0\.14\.75"/)
  assert.match(read(root, `app/build.gradle.kts`), /versionNameSuffix = "-staging"/)
  assert.match(read(root, `Project.swift`), /appMarketingVersion = "0\.15\.0"\nlet appBuildVersion = "222"/)
})

test(`dry run writes nothing`, () => {
  const root = fixture()
  const { plan, files } = bump({ config: CONFIG, requests: { desktop: `major`, ios: `patch` }, root, dryRun: true })
  assert.ok(plan.length >= 4)
  assert.deepEqual(files.sort(), [`Cargo.lock`, `Cargo.toml`, `Project.swift`, `excluded.json`])
  assert.equal(read(root, `Cargo.toml`), CARGO_TOML)
  assert.equal(read(root, `Project.swift`), SWIFT)
})

test(`a pattern matching 0 or >1 times fails loudly and writes nothing`, () => {
  const root = fixture()
  const zero = { products: { ios: { fields: [{ file: `Project.swift`, pattern: `^let nope = "(?<value>[^"]+)"$` }] } } }
  assert.throws(() => bump({ config: zero, requests: { ios: `patch` }, root }), (e) => e instanceof BumpError && /matched 0 times/.test(e.message))
  writeFileSync(join(root, `Project.swift`), SWIFT + `let appMarketingVersion = "0.14.72"\n`)
  assert.throws(() => bump({ config: CONFIG, requests: { android: `patch`, ios: `patch` }, root }), /matched 2 times/)
  assert.equal(read(root, `app/build.gradle.kts`), GRADLE)
})

test(`version fields that disagree fail`, () => {
  const root = fixture()
  writeFileSync(join(root, `other.txt`), `v = "0.14.80"\n`)
  const config = { products: { ios: { fields: [...CONFIG.products.ios.fields, { file: `other.txt`, pattern: `^v = "(?<value>[^"]+)"$` }] } } }
  assert.throws(() => bump({ config, requests: { ios: `patch` }, root }), /expected 0\.14\.72/)
})

test(`unknown product and missing value group fail`, () => {
  const root = fixture()
  assert.throws(() => bump({ config: CONFIG, requests: { spezl: `patch` }, root }), /unknown product "spezl"/)
  const bad = { products: { ios: { fields: [{ file: `Project.swift`, pattern: `appMarketingVersion` }] } } }
  assert.throws(() => bump({ config: bad, requests: { ios: `patch` }, root }), /no \(\?<value>/)
})

test(`versionFromTags picks the newest strict x.y.z tag`, () => {
  const root = fixture()
  const git = (...a) => execFileSync(`git`, a, { cwd: root, stdio: `pipe` })
  git(`init`, `-q`)
  git(`-c`, `user.email=t@t`, `-c`, `user.name=t`, `commit`, `-q`, `--allow-empty`, `-m`, `x`)
  for (const t of [`v0.9.0`, `v0.20.2`, `v0.20.10-dev`, `v0.3.0`, `desktop-v9.0.0`]) git(`tag`, t)
  const { results } = bump({ config: CONFIG, requests: { web: `patch` }, root })
  assert.equal(results[0].from, `0.20.2`)
  assert.deepEqual(results[0].tags, [`v0.20.3`])
})

test(`CLI: tags on stdout, plan on stderr, GITHUB_OUTPUT written, exit 1 on failure`, () => {
  const root = fixture()
  const out = join(root, `gh-output`)
  appendFileSync(out, ``)
  const stdout = execFileSync(process.execPath, [SCRIPT, `--config`, `release-versions.json`, `--root`, root, `desktop=patch`, `ios=none`, `android=patch`], {
    env: { ...process.env, GITHUB_OUTPUT: out },
    encoding: `utf8`,
    stdio: [`ignore`, `pipe`, `pipe`],
  })
  assert.equal(stdout, `desktop-v0.14.84\ncli-v0.14.84\nandroid-v0.14.75\n`)
  const gh = read(root, `gh-output`)
  assert.match(gh, /tags<<EXP_BUMP_EOF\ndesktop-v0\.14\.84\ncli-v0\.14\.84\nandroid-v0\.14\.75\nEXP_BUMP_EOF/)
  assert.match(gh, /versions=\{"desktop":\{"version":"0\.14\.84"\},"android":\{"version":"0\.14\.75","versionCode":"158"\}\}/)
  assert.throws(
    () => execFileSync(process.execPath, [SCRIPT, `--config`, `release-versions.json`, `--root`, root, `desktop=0.1.0`], { stdio: `pipe` }),
    (e) => e.status === 1 && /not above/.test(e.stderr.toString()),
  )
})
